/**
 * Simple Mode App - the portfolio as a plain document.
 *
 * Shows the printable CV (cv.html / cv.pl.html, generated by scripts/build-static.mjs
 * from config.js) inside the window, so Simple View and the CV are always the same
 * document instead of two copies that drift apart. The CV's own toolbar is hidden
 * and its links open in a new tab.
 */

import { Icons } from '../icons.js?v=17';
import { PortfolioApp } from './PortfolioApp.js?v=17';
import { t, lang } from '../i18n.js?v=17';

const cvFile = () => (lang === 'pl' ? 'cv.pl.html' : 'cv.html');
const frame = () => document.querySelector('#window-simplemode .simplemode-frame');

// Same origin, so the page can be adjusted after it loads
function prepare(iframe) {
    let doc;
    try { doc = iframe.contentDocument; } catch { return; }
    if (!doc?.head || doc.querySelector('[data-simple-view]')) return;
    const style = doc.createElement('style');
    style.dataset.simpleView = '';
    style.textContent = '.cv-toolbar { display: none !important; } @media screen { .cv-sheet { margin-top: 16px; } }';
    const base = doc.createElement('base');
    base.target = '_blank';
    doc.head.append(style, base);
    doc.querySelectorAll('a[href]').forEach(link => { link.rel = 'noopener noreferrer'; });
}

export const SimpleModeApp = {
    id: 'simplemode',
    title: 'Simple View',
    icon: Icons.simplemode,
    width: 700,
    height: 600,
    minWidth: 400,
    minHeight: 300,
    hasMenu: true,
    menuItems: ['File', 'View', 'Help'],

    menuConfig: {
        'File': [
            { label: 'Print...', action: 'print' },
            { divider: true },
            { label: 'Close', action: 'close', shortcut: 'Alt+F4' }
        ],
        'View': [
            { label: 'Refresh', action: 'refresh', shortcut: 'F5' }
        ],
        'Help': [
            { label: 'About Simple View', action: 'about' }
        ]
    },

    onMenuAction(action) {
        const iframe = frame();
        switch (action) {
            case 'print':
                // Only the CV, not the whole desktop
                try { iframe.contentWindow.print(); } catch { window.print(); }
                break;
            case 'refresh':
                try { iframe.contentWindow.location.reload(); } catch { if (iframe) iframe.src = cvFile(); }
                break;
        }
    },

    render() {
        return `
            <div class="simplemode-container">
                <div class="simplemode-toolbar">
                    <span>${Icons.fileText} ${t('simple.toolbar')}</span>
                    <button class="win-btn win-btn-sm" id="simplePrintBtn">${Icons.actPrint} ${t('simple.print')}</button>
                </div>
                <div class="simplemode-content">
                    <iframe class="simplemode-frame" src="${cvFile()}" title="CV"></iframe>
                </div>
            </div>
        `;
    },

    onInit() {
        const iframe = frame();
        iframe?.addEventListener('load', () => prepare(iframe));
        if (iframe?.contentDocument?.readyState === 'complete') prepare(iframe);

        // Same as Download CV elsewhere: the dot-matrix printer, then the CV
        document.querySelector('#simplePrintBtn')?.addEventListener('click', () => PortfolioApp.downloadCV());
    }
};

export default SimpleModeApp;
